/* Particle update: move with the camera offset when flagged, kill it when off the map or its timer ends, else fade its
   colour. */
void update_moving_hero_relative_alpha_fade_particle(struct PartBase *m) {
    struct PartType60Data *v = (struct PartType60Data *)m->data;
    int col;
    float a;
    if (v->mode == 1) {
        struct Hero *g = &g_hero;
        m->pos.f[0] = g->motion.pos.f[0] + v->hero_offset.x;
        m->pos.f[1] = g->motion.pos.f[1] + v->hero_offset.y;
        m->pos.f[2] = g->motion.pos.f[2] + v->hero_offset.z;
        FastVecAdd(&m->pos, &m->pos, &v->vel);
        v->hero_offset.x = m->pos.f[0] - g->motion.pos.f[0];
        v->hero_offset.y = m->pos.f[1] - g->motion.pos.f[1];
        v->hero_offset.z = m->pos.f[2] - g->motion.pos.f[2];
    } else {
        FastVecAdd(&m->pos, &m->pos, &v->vel);
    }
    if (m->pos.f[0] < 2.0f || m->pos.f[0] > 1021.0f || m->pos.f[1] < 2.0f || m->pos.f[1] > 1021.0f ||
        m->pos.f[2] < 2.0f || m->pos.f[2] > 1021.0f || FastDecTimer(&m->timer) != 0) {
        KillPart(m);
        return;
    }
    col = m->color & 0xFFFFFF;
    a = IntToFloat(m->timer - 1);
    m->color = FastTweenColor(col, m->color, a / IntToFloat(m->timer));
}

