/* Particle type 65 update: fall under gravity, bounce off the world, fade the colour and die when spent. Adapted from Lombyte's project (GPL-3.0) for PAL: overlays/shared/rendering_002712b8.c, FUN_L00_00273ee0. */
void update_line_collision_rgb_fading_particle(struct PartBase *o) {
    V out;
    float *c;
    unsigned char *b;
    float d;
    if (!o)
        return;
    c = (float *)o->data;
    b = (unsigned char *)&o->pos;
    d = frame_scale;
    c[7] += d * 0.0f;
    o->size += d * -100.0f;
    FastVecAdd(&out, b, c);
    if (c[0] != 0.0f || c[1] != 0.0f || c[2] != 0.0f) {
        if (coll_line(&o->pos, &out, 2, o, 0)) {
            *(V *)&o->pos = collision_hit_point;
            clear_u64_value(c);
            o->size += o->size;
        } else {
            *(V *)&o->pos = out;
            if (c[3] != 0.0f) {
                c[2] += c[3];
            } else {
                c[2] += g_frame_scale_sq * -0.006300000008195639f;
            }
        }
    }
    if (c[7] <= 0.0f || FastDecTimer(&o->timer) || o->size < 0.0f || ((float *)&out)[0] < 0.01f ||
        ((float *)&out)[1] < 0.01f || ((float *)&out)[2] < 0.01f) {
        KillPart(o);
        return;
    }
    c[4] += frame_scale * -0.01f;
    if (c[4] < 0.0f)
        c[4] = 0.0f;
    c[5] += frame_scale * -0.030009999871253967f;
    if (c[5] < 0.0f)
        c[5] = 0.0f;
    c[6] += frame_scale * -0.05f;
    if (c[6] < 0.0f)
        c[6] = 0.0f;
    c[7] += frame_scale * 0.0f;
    if (c[7] < 0.0f)
        c[7] = 0.0f;
    o->color = PackColorRGBA(c[4], c[5], c[6], c[7]);
    o->spin--;
}
