typedef struct R_274518 {
    f32 unk0;
    f32 unk4;
    f32 unk8;
    u8 *iC;
    f32 unk10;
    f32 unk14;
    s16 h18;
    s16 h1A;
    s16 h1C;
    u8 pad1E[2];
} R_274518;

typedef struct M_274518 {
    u8 b0;
    u8 b1;
    u8 b2;
    u8 b3;
    u8 b4[3];
    s8 b7;
    u8 b8;
    u8 b9;
    s16 hA;
    u8 pad0C[4];
    u8 v10[16];
    R_274518 r;
} M_274518;

// Update for an attached particle: follows its owner moby, spawns a child and orients itself.
void update_mode_controlled_orbiting_trail_particle(char *m) {
    M_274518 *particle = (M_274518 *)m;
    R_274518 *r = &particle->r;
    float vv[28];
    u8 *q;
    u8 *o;
    float z;
    float t, u, e;
    if (r->h1C == 0) {
        if (decrement_packed_countdown_q(particle->b4, r->h1A)) {
            KillPart(m);
            return;
        }
        if (r->iC == 0)
            return;
        vv[0] = r->unk0;
        vv[1] = r->unk4;
        vv[2] = r->unk8;
        FastVecScale(vv, vv, IntToFloat(r->h18));
        FastVecAdd(particle->v10, r->iC + 0x10, vv);
        return;
    }
    if (FastDecTimer(&particle->hA) ||
        (particle->hA < scale_ticks(10) && decrement_packed_countdown_q(particle->b4, 0x10))) {
        KillPart(m);
        return;
    }
    if (r->h1C == 1) {
        z = 0.0f;
        spawn_mode_controlled_orbiting_trail_particle_r(z, 0, particle->v10, z, scale_ticks(10), 0, particle->b7, 0);
        q = particle->v10;
    } else {
        vv[0] = r->unk0;
        vv[1] = r->unk4;
        vv[2] = r->unk8;
        z = 0.0f;
        o = spawn_mode_controlled_orbiting_trail_particle_r(z, r->iC, particle->v10, z, scale_ticks(10), 0,
                                                            particle->b7, vv);
        q = particle->v10;
        if (o != 0)
            *(s16 *)(o + 0x38) = *(u16 *)&r->h18;
    }
    if (r->h1C != 1)
        return;
    qcopy(q, r->iC + 0x10);
    vv[0] = FastCos(r->unk10) * 2.25f;
    vv[1] = FastSin(r->unk10) * 2.25f;
    vv[2] = vv[0];
    *(int *)&vv[0] = 0;
    vv[4] = FastCos(r->unk14) * 0.28f;
    vv[5] = FastSin(r->unk14) * 0.28f;
    vv[6] = vv[4];
    *(int *)&vv[4] = 0;
    clear_u64_value((vv + 8));
    vv[9] = r->unk10;
    euler_to_matrix((vv + 12), (vv + 8));
    transform_vector((vv + 4), (vv + 4), (vv + 12));
    FastVecAdd(vv, vv, (vv + 4));
    transform_vector_by_basis(vv, vv, r->iC + 0xC0);
    FastVecAdd(q, q, vv);
    t = FastAddRots(r->unk10, g_frame_time * 0.9599311f);
    u = g_frame_time * 4.3633232f;
    e = r->unk14;
    r->unk10 = t;
    r->unk14 = FastAddRots(e, u);
}

